using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using PaperPixelGames.Core.DressingSceneSystem;
public static partial class ScreenshotFollowupRepair {
 public static void PrepareRuntimeRetry(){applied=JsonUtility.FromJson<ApplyReceipt>(File.ReadAllText(Path.Combine(Reports,"screenshot-followup-applied.json")));var gs=EditorSceneManager.OpenScene(GS);var ds=EditorSceneManager.OpenScene(DS,OpenSceneMode.Additive);var source=EditorSceneManager.OpenScene(Source,OpenSceneMode.Additive);var from=All(source).Single(t=>t.name=="SideWalkTerrainEdge");var to=All(ds).Single(t=>t.name=="SideWalkTerrainEdge");ClipSidewalk(to,from);EditorSceneManager.CloseScene(source,true);var nodes=All(gs).Concat(All(ds)).ToArray();var activation=nodes.ToDictionary(t=>t.gameObject,t=>t.gameObject.activeSelf);foreach(var root in nodes.Select(t=>t.GetComponent<DressingSceneRoot>()).Where(r=>r))root.ActivateAllImmediate();Physics.SyncTransforms();AlignBenches(nodes);foreach(var pair in activation)if(pair.Key)pair.Key.SetActive(pair.Value);EditorSceneManager.MarkSceneDirty(gs);EditorSceneManager.MarkSceneDirty(ds);EditorSceneManager.SaveScene(gs);EditorSceneManager.SaveScene(ds);AssetDatabase.SaveAssets();ApplyStage("FINAL_CURB_AND_FURNITURE_SAVED");IslandFrontEndBuilder.RefreshMenuPresentation();InstallInteriorAndVerify();}
